use crate::aap::caps::kb_read;

struct Node;

/// Truncate `s` in place to at most `max` bytes, respecting char boundaries.
fn clamp_bytes(mut s: String, max: usize) -> String {
    if s.len() > max {
        let mut end = max;
        while end > 0 && !s.is_char_boundary(end) {
            end -= 1;
        }
        s.truncate(end);
    }
    s
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let inner = query.query;

        // ensures len(question) <= 512. The requires already guarantees this of
        // the input, but we clamp defensively so the ensures holds by construction.
        let question = clamp_bytes(inner.question, 512);

        // Read-only lookup against the 'knowledge-base' store — the node's sole
        // authority. Returns a typed list<string>.
        let mut knowledge = kb_read::lookup(&question);

        // ensures present(knowledge): the context must carry knowledge. If the
        // store returned nothing, supply an explicit placeholder so downstream
        // nodes see a present, non-empty field rather than an empty list.
        if knowledge.is_empty() {
            knowledge.push(String::from("no matching knowledge-base entries"));
        }

        ConversationContext {
            intent: inner.intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
```

